function announce(title,sub='',seconds=4){toastQueue.push({title,sub,life:seconds,max:seconds});}
const mixer=new window.CorgiAudio();
function sound(type='hit',vol=.08){mixer.play(type,vol)}
function audioStart(){mixer.start();music=mixer.music;syncAudioUI()}
function syncAudioUI(){for(const k of ['music','sfx']){$(k+'Volume').value=Math.round(mixer.settings[k]*100);$(k+'Value').textContent=Math.round(mixer.settings[k]*100)+'%'}$('muteAudio').textContent=mixer.settings.muted?'開啟聲音':'全部靜音';$('sound').textContent=mixer.settings.muted?'♫ 已靜音':'♫ 聲音設定'}
function setMute(){mixer.set('muted',!mixer.settings.muted);syncAudioUI()}
function puff(x,y,color,n=9,power=100){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-power,power),vy:rand(-power,power*.25),life:rand(.2,.6),color,size:rand(2,5)})}
function float(x,y,text,color='#ffe5a3'){texts.push({x,y,text,color,life:.8})}
function collectHeart(x,y){drops.push({x,y,kind:'heart',life:25,t:0})}
function enemy(type,x,y=G,room=-1){const hp={slime:70,guard:125,flyer:62}[type];return {type,x,y,baseY:y,vx:0,vy:0,hp,max:hp,dir:-1,state:'move',t:rand(.6,1.6),flash:0,burn:0,stun:0,room,dead:false,attackId:0}}
function makeLevel(){platforms=[];hazards=[];walls=[];lamps=[];pickups=[];gates=[];decor=[];enemies=[];shots=[];drops=[];particles=[];texts=[];boss=null;
for(let z=0;z<7;z++){let base=z*3200;lamps.push({x:base+160,on:z===0});for(let j=0;j<4;j++){let x=base+500+j*610;let pattern=j%3;let steps=pattern===0?[[0,72,180],[235,144,190]]:pattern===1?[[0,60,190],[245,120,200],[485,180,180]]:[[0,72,220],[270,72,190]];for(const [dx,rise,width] of steps){platforms.push({x:x+dx,y:G-rise,w:width,h:16});for(let k=0;k<3;k++)pickups.push({x:x+dx+45+k*38,y:G-rise-28,kind:'coin',taken:false})}decor.push({x:x+210,kind:j%3});if(j===2)hazards.push({x:x+70,w:70});}}
const centres=[2500,5750,9050,12600,16350,20200];centres.forEach((x,i)=>{if(i!==2)gates.push({x,index:i,active:false,clear:false,wave:0,spawnT:0,medal:[1,3,5].includes(i)})});
for(let z=0;z<7;z++)for(let i=0;i<3;i++)enemies.push(enemy(i===2?'flyer':i===1?'guard':'slime',z*3200+1000+i*450,i===2?G-100:G));
walls=[{x:4700,w:44,h:92,kind:1,hp:70},{x:11100,w:55,h:110,kind:2,hp:1},{x:18000,w:70,h:150,kind:3,hp:999}];
pickups.push({x:760,y:G-30,kind:'form',form:1,taken:false},{x:6800,y:G-30,kind:'form',form:2,taken:false},{x:14600,y:G-30,kind:'form',form:3,taken:false});
for(let x=1400;x<22000;x+=1800)pickups.push({x,y:G-38,kind:'heart',taken:false});shapeStreet();}

// Continuous terrain phrases: introduce a low step, vary its spacing and height,
// then combine it with a familiar obstacle. No extra gates, timers or objectives.
function shapeStreet(){
 const routes=[
  [[500,60,200],[750,120,200],[1280,60,240],[1590,120,230]],
  [[550,60,200],[800,120,220],[1080,60,230],[1810,60,220],[2080,120,220]],
  [[680,60,210],[940,120,220],[1220,180,240],[1520,120,240],[1820,60,230],[2260,60,230],[2550,120,240],[2850,60,230]],
  [[480,60,210],[740,120,240],[1040,120,240],[1750,60,220],[2040,120,230],[2330,60,220]],
  [[580,60,220],[860,60,220],[1150,60,220],[1750,60,220],[2010,120,230],[2300,180,250],[2630,120,240],[2930,60,220]],
  [[1080,60,190],[1320,120,190],[1560,180,220],[1830,180,260],[2150,120,220],[2750,60,220],[3020,120,230]],
  [[1700,60,220],[1970,120,230],[2240,60,230],[2700,60,220]]
 ];
 platforms=[];pickups=pickups.filter(p=>p.kind!=='coin');hazards=[];
 routes.forEach((route,z)=>route.forEach(([dx,rise,w])=>{
  const x=z*3200+dx;platforms.push({x,y:G-rise,w,h:16});
  // Coins trace the upper route without introducing a collection requirement.
  for(let i=0;i<2;i++)pickups.push({x:x+65+i*65,y:G-rise-28,kind:'coin',taken:false});
 }));
 crates=[3280,3530,3585,7150,9220,9280,13080,14770,14825,20820].map(x=>({x,w:42,h:36,broken:false,supply:x===9220||x===20820}));
 // First vent is isolated; later pairs sit below generous, safe stepping routes.
 vents=[{x:8440,w:58,offset:0},{x:13470,w:60,offset:0},{x:13800,w:60,offset:1.1},{x:14110,w:60,offset:2.2},{x:21800,w:58,offset:.8}];
 // About half the former roaming density, with breathing room around new terrain.
 enemies=[['slime',1100],['guard',1900],['slime',4390],['flyer',7750],['slime',9620],['guard',11700],['slime',14550],['flyer',18800],['slime',21100],['guard',21650]].map(([type,x])=>enemy(type,x,type==='flyer'?G-110:G));
 decor=decor.filter(d=>!crates.some(c=>Math.abs(d.x-c.x)<65)&&!vents.some(v=>Math.abs(d.x-v.x)<90));
}
function breakCrate(c){
 if(c.broken)return;c.broken=true;player.coins+=2;stats.coins+=2;
 puff(c.x,G-20,'#eac28b',12,130);sound('impact',.04);float(c.x,G-42,'+2','#ffe3a2');
 if(c.supply)collectHeart(c.x,G-25);save();
}
function collideCrates(oldx,oldy){
 for(const c of crates){
  if(c.broken||Math.abs(player.x-c.x)>c.w/2+21)continue;
  const top=G-c.h;
  if(player.form===1&&player.dash>0&&player.y>top&&player.y-player.h<G){breakCrate(c);continue}
  if(oldy<=top+3&&player.y>=top&&player.vy>=0){player.y=top;player.vy=0;player.on=true}
  else if(player.y>top+2&&player.y-player.h<G){player.x=c.x+(oldx<c.x?-1:1)*(c.w/2+22);player.vx=0}
 }
}
function ventState(v){const t=(clock+v.offset)%4;return t<2.2?'off':t<3?'warn':'on'}
function drawStreetObjects(){
 for(const c of crates){if(c.broken)continue;let x=c.x-cam;if(x<-60||x>W+60)continue;
  rect(x-c.w/2,G-c.h,c.w,c.h,'#765047');rect(x-c.w/2+3,G-c.h+3,c.w-6,c.h-6,'#dfae73');
  rect(x-c.w/2+3,G-20,c.w-6,4,'#9e694e');rect(x-2,G-c.h+3,4,c.h-6,'#9e694e');
  if(c.supply)text('♥',x,G-12,15,'#f9d2b1','center');
 }
 for(const v of vents){let x=v.x-cam;if(x+v.w<0||x>W)continue;let state=ventState(v),color=state==='on'?'#ff8d73':state==='warn'?'#ffdf80':'#96d7bb';
  rect(x,G-6,v.w,8,'#45394e');for(let i=5;i<v.w;i+=12)rect(x+i,G-4,6,4,color);
  if(state==='on')for(let i=8;i<v.w;i+=17){let h=35+Math.sin(clock*12+i)*10;rect(x+i,G-h,9,h,'#ffc7a36e');rect(x+i+2,G-h,5,h,'#ffe5b963')}
  if(state==='warn'){rect(x,G-9,v.w,2,'#ffdf8099');for(let i=10;i<v.w;i+=18)rect(x+i,G-15,2,4,'#ffdf80')}
 }
}

function start(resume=false){clearInput();assist=$('assist').checked;makeLevel();player={x:120,y:G,vx:0,vy:0,w:42,h:43,hp:assist?160:120,max:assist?160:120,energy:100,form:0,unlocked:[true,false,false,false],dir:1,on:true,coyote:.12,jumpBuffer:0,jumpHold:0,jumps:0,dash:0,dashCd:0,atk:0,atkCd:0,skillCd:0,inv:0,combo:0,comboT:0,coins:0,medals:0,attackId:0};stats={kills:0,deaths:0,coins:0,time:0};levelTime=0;bossTime=0;checkpoint=120;cam=0;clock=0;zone=-1;toast=null;toastQueue=[];
if(resume&&saved){player.x=saved.x;checkpoint=saved.x;player.unlocked=saved.unlocked;player.form=saved.form;player.coins=saved.coins;levelTime=saved.time||0;stats={...stats,...saved.stats};gates.forEach(g=>g.clear=!!saved.gates?.[g.index]);crates.forEach(c=>c.broken=!!saved.brokenCrates?.includes(c.x));player.medals=gates.filter(g=>g.clear&&g.medal).length;walls.forEach((w,i)=>{if(saved.walls?.[i])w.hp=0});pickups.forEach(p=>{if(p.kind==='form'&&player.unlocked[p.form])p.taken=true});lamps.forEach(l=>l.on=l.x<=player.x);enemies=enemies.filter(e=>e.x>player.x-400);cam=clamp(player.x-280,0,LENGTH-W)}
mode='play';$('menu').classList.add('hidden');$('dialog').classList.add('hidden');cv.focus();audioStart();mixer.setScene('street',true);announce(resume?'路燈還為你亮著':'找到街角的她','← → 移動 · 空白鍵跳躍 · J 攻擊 · K 閃避',6);}
function save(){const data={x:checkpoint,unlocked:player.unlocked,form:player.form,coins:player.coins,time:levelTime,stats,gates:Array.from({length:6},(_,i)=>i===2||!!gates.find(g=>g.index===i)?.clear),brokenCrates:crates.filter(c=>c.broken).map(c=>c.x),walls:walls.map(w=>w.hp<=0)};try{localStorage.setItem('sunset-corgi-v1',JSON.stringify(data));saved=data;$('continue').hidden=false}catch{}}
function damagePlayer(n,sourceX){if(player.inv>0||player.dash>0||mode!=='play')return;const mult=(assist?.6:1)*(player.form===1?.75:1);player.hp-=Math.ceil(n*mult);player.inv=1.0;player.vx=(player.x<sourceX?-1:1)*230;player.vy=-210;player.on=false;shake=7;sound('hurt');puff(player.x,player.y-25,'#ff8d83');if(player.hp<=0){player.hp=0;stats.deaths++;mode='dead';showDialog('再試一次，短腿英雄。',`<p>路燈記住了你的進度。已解鎖的變身會保留。${boss?' BOSS 戰可立即重挑，不必重跑街區。':''}</p><p>提示：K 閃避有短暫無敵；BOSS 出現金色星星時，是最好的進攻機會。</p>`,'從存檔點重來',()=>respawn())}}
function respawn(){const wasBoss=!!boss;mode='play';$('dialog').classList.add('hidden');player.hp=player.max;player.energy=100;player.inv=2;player.vx=player.vy=0;player.y=G;player.on=true;player.dash=0;shots=[];if(wasBoss){player.x=BOSS_START+130;spawnBoss()}else{player.x=checkpoint;enemies=enemies.filter(e=>e.room<0&&e.x>checkpoint-500);gates.filter(g=>g.active&&!g.clear).forEach(g=>{g.active=false;g.wave=0})}cv.focus()}
function hurtEnemy(e,dmg,knock=90){if(e.dead)return;if(e.type==='guard'&&e.state==='guard'&&player.form!==1&&player.form!==2)dmg=Math.max(3,Math.floor(dmg*.22));sound('impact',.055);e.hp-=dmg;e.flash=.12;e.stun=.16;e.x+=Math.sign(e.x-player.x)*knock*.08;float(e.x,e.y-55,Math.round(dmg));puff(e.x,e.y-25,forms[player.form].color,5,90);player.energy=Math.min(100,player.energy+2);stats.hits=(stats.hits||0)+1;if(e.hp<=0){e.dead=true;stats.kills++;player.coins+=3;stats.coins+=3;sound('coin',.035);if(Math.random()<.15)collectHeart(e.x,e.y-25);puff(e.x,e.y-25,'#ffd18a',16,150)}}
function hurtBoss(dmg){if(!boss||boss.dead||boss.state==='intro')return;let open=boss.state==='rest';const dealt=dmg*(open?1:.13);boss.hp-=dealt;boss.flash=.08;float(boss.x+rand(-20,20),boss.y-120,open?Math.round(dealt):'防守',open?'#ffe9a1':'#b6a6b6');player.energy=Math.min(100,player.energy+1.5);if(open){sound('impact',.065);puff(boss.x,boss.y-90,'#ffe5a3',4);shake=2}if(boss.hp<=0){boss.hp=0;boss.dead=true;boss.state='defeated';boss.t=0;mixer.setScene('reunion');shots=shots.filter(s=>s.friendly);player.hp=Math.min(player.max,player.hp+50);announce('發條停了，街燈亮了。','向右走，女主人正在等你。',7);puff(boss.x,boss.y-80,'#ffc77a',70,260);sound('win');try{localStorage.removeItem('sunset-corgi-v1')}catch{}}}
function fire(x,y,vx,vy,friendly=true,damage=24,kind='fire'){shots.push({x,y,vx,vy,friendly,damage,kind,life:kind==='wave'?3:2.5,r:kind==='wave'?16:8,hit:new Set()})}
function attack(){if(player.atkCd>0||player.dash>.08)return;player.combo=player.comboT>0?(player.combo+1)%3:0;player.comboT=.9;player.atk=.20;player.atkCd=player.form===1?.42:.31;player.attackId++;sound('hit',.055);if(player.form===2){fire(player.x+player.dir*35,player.y-27,player.dir*500,0,true,forms[2].damage);return}const reach=player.form===3?104:88,damage=forms[player.form].damage*(player.combo===2?1.45:1);let any=false;for(const e of enemies){if(e.dead)continue;if(Math.abs(e.x-player.x)<reach&&Math.abs((e.y-25)-(player.y-24))<70&&(e.x-player.x)*player.dir>-20){hurtEnemy(e,damage);any=true}}if(boss&&!boss.dead&&Math.abs(boss.x-player.x)<155&&Math.abs(player.y-boss.y)<145){hurtBoss(damage);any=true}for(const w of walls){if(w.hp>0&&w.kind===1&&player.form===1&&Math.abs(w.x-player.x)<110){w.hp-=damage;puff(w.x,G-40,'#efba75',10);if(w.hp<=0){announce('酥皮牆碎了','麵包騎士可以擊碎硬殼與盾牌。');sound('skill')}}}for(const c of crates)if(!c.broken&&Math.abs(c.x-player.x)<reach&&Math.abs(G-20-(player.y-24))<65&&(c.x-player.x)*player.dir>-20)breakCrate(c);if(any){shake=3;hitstop=.045}}
function skill(){if(player.energy<30||player.skillCd>0)return;player.energy-=30;player.attackId++;player.skillCd=2.2;player.atk=.4;player.inv=Math.max(player.inv,.35);sound('skill');puff(player.x,player.y-30,forms[player.form].color,20,180);if(player.form===2){for(let i=-2;i<=2;i++)fire(player.x,player.y-30,player.dir*(450-Math.abs(i)*20),i*85,true,36)}else if(player.form===1){player.dash=.46;player.vx=player.dir*670;player.skillDash=true}else{const r=player.form===3?180:140;for(const e of enemies)if(!e.dead&&Math.abs(e.x-player.x)<r&&Math.abs(e.y-player.y)<140)hurtEnemy(e,player.form===3?65:48,180);if(boss&&!boss.dead&&Math.abs(boss.x-player.x)<r+65)hurtBoss(player.form===3?85:58);if(player.form===3){player.vy=-310;player.on=false}}}
function changeForm(n=null){let next=n;if(next===null){next=player.form;do{next=(next+1)%4}while(!player.unlocked[next])}if(!player.unlocked[next]||next===player.form)return;player.form=next;sound('skill',.06);puff(player.x,player.y-35,forms[next].color,24);announce(forms[next].name,forms[next].desc,3);save()}
function interact(){if(boss?.dead&&player.x>23600){win();return}if(!boss&&player.x>22200){if(player.medals<3){announce('鐘樓大門尚未開啟','完成街區戰鬥，集齊 3 枚烘焙徽章。');return}player.x=BOSS_START+130;checkpoint=player.x;save();spawnBoss();return}let lamp=lamps.find(l=>Math.abs(l.x-player.x)<100);if(lamp){checkpoint=lamp.x;player.hp=player.max;player.energy=100;lamp.on=true;save();announce('路燈存檔','生命與能量已補滿。',2);sound('coin')}}
function spawnBoss(){boss={x:BOSS_START+760,y:G,hp:BOSS_HP*(assist?.72:1),max:BOSS_HP*(assist?.72:1),phase:1,state:'intro',t:2.0,move:0,dir:-1,targetX:0,flash:0,dead:false,jumpStart:0,hit:false,shotT:0};bossTime=0;enemies=[];shots=[];mixer.setScene('boss',true);announce('BOSS · 發條烘焙師','避開紅色預警，在金色硬直時反擊。',5);}
function updateBoss(dt){if(!boss)return;let b=boss;if(b.dead){b.t+=dt;return}bossTime+=dt;b.flash=Math.max(0,b.flash-dt);b.t-=dt;let phase=b.hp/b.max>.66?1:b.hp/b.max>.33?2:3;if(phase>b.phase){b.phase=phase;announce(phase===2?'烤爐升溫':'最後一爐！',phase===2?'衝撞後追加火焰。留意地面波紋。':'連續招式更快；最後一次攻擊後才會露出破綻。',4);puff(b.x,b.y-80,'#ff9b63',35)}
if(b.state==='intro'){if(b.t<=0){b.state='rest';b.t=1.8}return}
if(b.state==='rest'){if(b.t<=0){b.move++;b.dir=player.x<b.x?-1:1;b.targetX=clamp(player.x,BOSS_START+100,BOSS_START+1250);b.hit=false;let pattern=(b.move-1)%4;b.state=['chargeWind','slamWind','volleyWind','spinWind'][pattern];b.t=[1.05,.9,.9,1.0][pattern]-(b.phase-1)*.09}return}
if(b.state==='chargeWind'){if(b.t<=0){b.state='charge';b.t=.98;b.hit=false}}
else if(b.state==='charge'){b.x+=b.dir*(b.phase===3?650:540)*dt;if(Math.abs(b.x-player.x)<95&&Math.abs(player.y-G)<110&&!b.hit){damagePlayer(23,b.x);b.hit=true}if(b.t<=0||b.x<BOSS_START+120||b.x>BOSS_START+1190){b.x=clamp(b.x,BOSS_START+120,BOSS_START+1190);if(b.phase>=2){fire(b.x,G-12,-260,0,false,17,'wave');fire(b.x,G-12,260,0,false,17,'wave')}b.state='rest';b.t=2.25}}
else if(b.state==='slamWind'){if(b.t<=0){b.state='slam';b.t=1.1;b.jumpStart=b.x}}
else if(b.state==='slam'){let u=clamp(1-b.t/1.1,0,1);b.x=lerp(b.jumpStart,b.targetX,u);b.y=G-Math.sin(u*Math.PI)*230;if(b.t<=0){b.y=G;shake=12;puff(b.x,G,'#ffc281',35,250);if(Math.abs(player.x-b.x)<125&&player.y>G-75)damagePlayer(27,b.x);fire(b.x,G-12,-300,0,false,18,'wave');fire(b.x,G-12,300,0,false,18,'wave');b.state='rest';b.t=2.5}}
else if(b.state==='volleyWind'){if(b.t<=0){b.state='volley';b.t=2.2;b.shotT=0}}
else if(b.state==='volley'){b.shotT-=dt;if(b.shotT<=0){b.shotT=b.phase===3?.30:.48;let aim=Math.atan2(player.y-25-(b.y-110),player.x-b.x);fire(b.x,b.y-110,Math.cos(aim)*300,Math.sin(aim)*300,false,16,'dough');if(b.phase===3)fire(b.x,b.y-110,Math.cos(aim+.25)*260,Math.sin(aim+.25)*260,false,14,'dough')}if(b.t<=0){b.state='rest';b.t=2.2}}
else if(b.state==='spinWind'){if(b.t<=0){b.state='spin';b.t=1.65;b.hit=false}}
else if(b.state==='spin'){b.x+=b.dir*180*dt;b.x=clamp(b.x,BOSS_START+120,BOSS_START+1190);if(Math.abs(player.x-b.x)<145&&Math.abs(player.y-b.y)<90){damagePlayer(20,b.x)}if(b.t<=0){b.state='rest';b.t=2.4}}
}
function win(){mode='win';winTime=clock;mixer.setScene('reunion');try{localStorage.removeItem('sunset-corgi-v1');saved=null}catch{}showDialog('找到你了。',`<p>黃昏麵包街重新亮起了燈。<br>而你要找的那個人，一直都在等你。</p><table><tr><td>街區用時</td><td>${fmt(levelTime)}</td></tr><tr><td>BOSS 用時</td><td>${fmt(bossTime)}</td></tr><tr><td>擊退敵人</td><td>${stats.kills}</td></tr><tr><td>收集餅乾</td><td>${player.coins}</td></tr><tr><td>跌倒後再站起</td><td>${stats.deaths} 次</td></tr></table>`,'再冒險一次',()=>start(false))}
let dialogAction=null;
function showDialog(title,body,button,action){$('dialogTitle').textContent=title;$('dialogBody').innerHTML=body;$('dialogClose').textContent=button;dialogAction=action;$('dialog').classList.remove('hidden')}
function pause(){if(mode==='play'){clearInput();mode='pause';showDialog('在路燈下歇一歇。','<p>你的冒險已暫停。<br>Q 切換已解鎖的變身，L 使用技能。路燈旁按 E 補給與存檔。</p>','繼續冒險',()=>{mode='play';$('dialog').classList.add('hidden');cv.focus()})}else if(mode==='pause'){$('dialogClose').click()}}
function help(){previousMode=mode;if(mode==='play')mode='pause';showDialog('冒險手冊',`<table><tr><td>← → / A D</td><td>移動</td></tr><tr><td>空白鍵 / W / ↑</td><td>跳躍；疾風形態可二段跳</td></tr><tr><td>J / 滑鼠左鍵</td><td>攻擊，按住可連擊</td></tr><tr><td>K / Shift</td><td>閃避，短暫無敵</td></tr><tr><td>L</td><td>技能，消耗 30 能量</td></tr><tr><td>Q / 1–4</td><td>切換已解鎖的變身</td></tr><tr><td>E</td><td>路燈補給／大門／重逢</td></tr><tr><td>Esc / P</td><td>暫停</td></tr></table><p>手柄：左搖桿移動，A 跳躍、X 攻擊、B 閃避、Y 技能、LB 變身、RB 互動。<br>街區保留五場單批遭遇戰。箱子可打碎或跳過；地面黃光表示即將噴氣，熄滅後即可通過。BOSS 血量已減少 62.5%。</p>`,'知道了',()=>{mode=previousMode;$('dialog').classList.add('hidden');cv.focus()})}
function update(dt){clock+=dt;if(mode!=='play'){updateEffects(dt);return}stats.time+=dt;if(!boss)levelTime+=dt;if(hitstop>0){hitstop-=dt;return}for(let k of ['atk','atkCd','dashCd','skillCd','inv','comboT','jumpHold'])player[k]=Math.max(0,player[k]-dt);player.energy=Math.min(100,player.energy+dt*5.5);if(player.on){player.coyote=.14;player.jumps=0}else player.coyote-=dt;
if(pressed.jump)player.jumpBuffer=.16;else player.jumpBuffer=Math.max(0,player.jumpBuffer-dt);
if(player.jumpBuffer>0&&(player.coyote>0||(player.form===3&&player.jumps<2))){player.vy=player.form===3?-570:-540;player.on=false;player.coyote=0;player.jumps++;player.jumpHold=.14;player.jumpBuffer=0;sound('jump',.035);puff(player.x,player.y,'#eac7a0',5,80)}if(!keys.jump&&player.jumpHold<=0&&player.vy<-210)player.vy+=1100*dt;
if(pressed.dash&&player.dashCd<=0){player.dash=.26;player.dashCd=.9;player.vx=player.dir*(player.form===3?730:640);player.skillDash=false;sound('dash',.04)}if(pressed.form)changeForm();for(let i=0;i<4;i++)if(pressed['form'+i])changeForm(i);if(pressed.skill)skill();if(pressed.interact)interact();if(keys.attack)attack();
let move=(keys.right?1:0)-(keys.left?1:0);if(move)player.dir=move;let oldx=player.x,oldy=player.y;
if(player.dash>0){player.dash-=dt;player.vy*=.82;if(player.skillDash){for(let e of enemies)if(!e.dead&&Math.abs(e.x-player.x)<80&&Math.abs(e.y-player.y)<60&&e.attackId!==player.attackId){e.attackId=player.attackId;hurtEnemy(e,75)}if(boss&&!boss.dead&&Math.abs(boss.x-player.x)<140&&!player.bossDashed){hurtBoss(100);player.bossDashed=true}}puff(player.x-player.dir*25,player.y-24,forms[player.form].color,1,20)}else{player.skillDash=false;player.bossDashed=false;player.vx=lerp(player.vx,move*(player.form===3?265:235),Math.min(1,dt*(player.on?19:10)));player.vy+=1350*dt}
player.x+=player.vx*dt;player.y+=player.vy*dt;player.on=false;if(player.y>=G){player.y=G;player.vy=0;player.on=true}for(let pl of platforms){if(player.x>pl.x-15&&player.x<pl.x+pl.w+15&&oldy<=pl.y+3&&player.y>=pl.y&&player.vy>=0){player.y=pl.y;player.vy=0;player.on=true}}
collideCrates(oldx,oldy);
for(let wall of walls){if(wall.hp>0&&player.y>G-wall.h&&Math.abs(player.x-wall.x)<wall.w/2+22){if(oldx<wall.x)player.x=wall.x-wall.w/2-22;else player.x=wall.x+wall.w/2+22;if(Math.abs(player.vx)>5&&Math.floor(clock/3)!==Math.floor((clock-dt)/3))announce(wall.kind===1?'酥皮牆':wall.kind===2?'焦糖荊棘':'高高的屋脊',wall.kind===1?'切換麵包騎士，用攻擊擊碎。':wall.kind===2?'切換火花柯基，用火球點燃。':'疾風形態可以二段跳。',2);player.vx=0}}
for(const v of vents)if(ventState(v)==='on'&&player.x>v.x-8&&player.x<v.x+v.w+8&&player.y>G-48)damagePlayer(6,v.x+v.w/2);
for(let h of hazards)if(player.x>h.x&&player.x<h.x+h.w&&player.y>G-10)damagePlayer(12,h.x+h.w/2);
for(let g of gates){if(!g.clear&&!g.active&&player.x>g.x-250&&player.x<g.x+330){g.active=true;g.wave=0;g.spawnT=.6;announce('街區遭遇戰',g.medal?'擊退這批敵人，取得烘焙徽章。':'擊退這批敵人，打開街口。',3)}if(g.active&&!g.clear){player.x=clamp(player.x,g.x-350,g.x+340);let live=enemies.filter(e=>e.room===g.index&&!e.dead);if(live.length===0){g.spawnT-=dt;if(g.spawnT<=0){if(g.wave>=1){g.clear=true;g.active=false;player.hp=Math.min(player.max,player.hp+28);player.energy=Math.min(100,player.energy+30);if(g.medal){player.medals++;announce('烘焙徽章 '+player.medals+' / 3','街口開了！路燈會為你補給。',3)}else announce('街口暢通','生命 +28 · 能量 +30',2);save()}else{g.wave++;g.spawnT=.7;for(let j=0;j<4;j++){let type=(g.index+g.wave+j)%5===0?'flyer':j%3===0?'guard':'slime';let x=g.x+(j%2?1:-1)*(150+Math.floor(j/2)*110);enemies.push(enemy(type,x,type==='flyer'?G-90:G,g.index))}sound('hurt',.02)}}}}}
if(!boss)player.x=clamp(player.x,30,BOSS_START+20);else if(!boss.dead)player.x=clamp(player.x,BOSS_START+45,BOSS_START+1300);else player.x=clamp(player.x,30,LENGTH-90);
for(let l of lamps){if(!l.on&&Math.abs(player.x-l.x)<65){l.on=true;checkpoint=l.x;player.hp=player.max;player.energy=100;save();announce('路燈已點亮','已存檔 · 生命與能量恢復',2.5)}}
for(let p of pickups){if(!p.taken&&Math.abs(player.x-p.x)<45&&Math.abs(player.y-25-p.y)<55){p.taken=true;if(p.kind==='form'){player.unlocked[p.form]=true;changeForm(p.form);announce('獲得變身道具',forms[p.form].desc+' · Q 切換 · L 技能',6);save()}else if(p.kind==='heart'){player.hp=Math.min(player.max,player.hp+26);float(player.x,player.y-60,'+26','#ffadb6');sound('coin',.04)}else{player.coins++;stats.coins++;player.energy=Math.min(100,player.energy+1);sound('coin',.018)}}}
for(let d of drops){d.life-=dt;d.t+=dt;if(Math.abs(player.x-d.x)<42&&Math.abs(player.y-25-d.y)<55){d.life=0;player.hp=Math.min(player.max,player.hp+20);float(player.x,player.y-55,'+20','#ffadb6')}}drops=drops.filter(d=>d.life>0);
for(let e of enemies){if(e.dead||Math.abs(e.x-player.x)>900)continue;e.flash=Math.max(0,e.flash-dt);if(e.burn>0){e.burn-=dt;e.hp-=12*dt;if(e.hp<=0){hurtEnemy(e,1);continue}}if(e.stun>0){e.stun-=dt;continue}e.t-=dt;e.dir=player.x<e.x?-1:1;let dx=Math.abs(player.x-e.x);
if(e.type==='slime'){if(e.state==='move'){e.x+=e.dir*62*dt;if(e.t<=0&&dx<270){e.state='wind';e.t=.52}}else if(e.state==='wind'){if(e.t<=0){e.state='hop';e.t=.58;e.vx=e.dir*270;e.vy=-260}}else if(e.state==='hop'){e.x+=e.vx*dt;e.vy+=1150*dt;e.y+=e.vy*dt;if(e.y>=G){e.y=G;e.state='move';e.t=1.1}}}
else if(e.type==='guard'){if(e.state==='move'||e.state==='guard'){e.state=dx<170?'guard':'move';if(dx>110)e.x+=e.dir*44*dt;if(e.t<=0&&dx<150){e.state='wind';e.t=.65}}else if(e.state==='wind'){if(e.t<=0){e.state='strike';e.t=.3;sound('hit',.025)}}else if(e.state==='strike'){if(dx<135&&Math.abs(player.y-e.y)<65)damagePlayer(17,e.x);if(e.t<=0){e.state='move';e.t=1.8}}}
else{e.y=e.baseY+Math.sin(clock*3+e.x*.01)*20;e.x+=e.dir*(dx>250?65:15)*dt;if(e.t<=0){let a=Math.atan2(player.y-25-e.y,player.x-e.x);fire(e.x,e.y,Math.cos(a)*210,Math.sin(a)*210,false,11,'crumb');e.t=2.6}}
if(dx<35&&Math.abs(player.y-23-(e.y-22))<37){if(player.vy>100&&oldy<e.y-35){hurtEnemy(e,42);player.vy=-320;player.on=false}else damagePlayer(e.type==='slime'?11:13,e.x)}}
enemies=enemies.filter(e=>!e.dead);
for(let s of shots){s.life-=dt;s.x+=s.vx*dt;s.y+=s.vy*dt;if(s.friendly){for(const c of crates)if(!c.broken&&s.life>0&&Math.abs(s.x-c.x)<30&&s.y>G-c.h-8&&s.y<G+8){breakCrate(c);s.life=0}for(let e of enemies)if(!e.dead&&!s.hit.has(e)&&Math.abs(s.x-e.x)<34&&Math.abs(s.y-(e.y-25))<40){s.hit.add(e);hurtEnemy(e,s.damage);e.burn=2;s.life=0}if(boss&&!boss.dead&&!s.hit.has(boss)&&Math.abs(s.x-boss.x)<75&&Math.abs(s.y-(boss.y-78))<83){s.hit.add(boss);hurtBoss(s.damage);s.life=0}for(let w of walls)if(w.hp>0&&w.kind===2&&Math.abs(s.x-w.x)<35&&s.y>G-w.h){w.hp=0;s.life=0;puff(w.x,G-55,'#ffad62',28);announce('火焰開路','荊棘燒盡了。',2)}}else if(Math.abs(s.x-player.x)<24+s.r&&Math.abs(s.y-(player.y-23))<24+s.r){damagePlayer(s.damage,s.x);s.life=0}if(s.y>H+100||s.y<-300)s.life=0}shots=shots.filter(s=>s.life>0);
updateBoss(dt);let nz=clamp(Math.floor(player.x/3200),0,6);if(nz!==zone&&!boss){zone=nz;announce(names[nz],`黃昏麵包街 · ${nz+1} / 7`,3)}let desired=clamp(player.x-W*.35,0,LENGTH-W);cam=lerp(cam,desired,Math.min(1,dt*7));updateEffects(dt);pressed={};}
function updateEffects(dt){shake=Math.max(0,shake-35*dt);for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=300*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);for(let t of texts){t.y-=25*dt;t.life-=dt}texts=texts.filter(t=>t.life>0);if(!toast&&toastQueue.length)toast=toastQueue.shift();if(toast){toast.life-=dt;if(toast.life<=0)toast=null}if(toastQueue.length>5)toastQueue.splice(1,toastQueue.length-5)}
function sprite(name,x,y,w,flip=false,alpha=1){let im=imgs[name];if(!im)return;let h=w*im.height/im.width;ctx.save();ctx.globalAlpha=alpha;ctx.translate(Math.round(x),Math.round(y));if(flip)ctx.scale(-1,1);ctx.drawImage(im,-w/2,-h,w,h);ctx.restore()}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function text(s,x,y,size=14,color='#f8e9cc',align='left'){ctx.font=`${size>=22?'900':'600'} ${size}px "Noto Sans TC",system-ui,sans-serif`;ctx.textAlign=align;ctx.fillStyle=color;ctx.fillText(s,Math.round(x),Math.round(y))}
function bar(x,y,w,h,value,color,bg='#231e32'){rect(x,y,w,h,bg);rect(x+2,y+2,(w-4)*clamp(value,0,1),h-4,color)}
